//! Generates `crates/iw-keymap/src/table.rs` from Chromium's
//! `dom_code_data.inc`, which maps USB HID usages to macOS virtual key codes,
//! Windows scan codes and Linux evdev codes; and from the same table, for
//! the apps' shortcut recorders, the UI Events `code` name of each macOS
//! virtual key code (Swift) and Windows scan code (C#), the names hotkeys
//! are written with.

use std::collections::BTreeMap;
use std::fmt::Write;

/// The table this repository keeps, and the code generated from it.
pub const SOURCE: &str = "third_party/chromium/dom_code_data.inc";
pub const OUTPUT: &str = "crates/iw-keymap/src/table.rs";
pub const SWIFT_OUTPUT: &str = "apps/macos/InputWeave/Generated/KeyCodes.swift";
pub const CSHARP_OUTPUT: &str = "apps/windows/InputWeave.Core/Generated/KeyCodes.cs";

/// Every file generated from the table, with what goes in it.
pub fn outputs(source: &str) -> Result<Vec<(&'static str, String)>, String> {
    Ok(vec![
        (OUTPUT, generate(source)?),
        (SWIFT_OUTPUT, generate_swift(source)?),
        (CSHARP_OUTPUT, generate_csharp(source)?),
    ])
}

/// The heading of each generated file, after its comment marker.
const HEADING: [&str; 3] = [
    "@generated by `cargo xtask keymap` from third_party/chromium/dom_code_data.inc.",
    "Do not edit by hand. The source table is Chromium's (BSD-3-Clause); see",
    "THIRD_PARTY_NOTICES.md.",
];

fn heading(out: &mut String) {
    for line in HEADING {
        writeln!(out, "// {line}").unwrap();
    }
    out.push('\n');
}

/// The macOS app's table: virtual key code to name.
pub fn generate_swift(source: &str) -> Result<String, String> {
    let entries = parse(source)?;
    let named: Vec<(u16, &str)> = entries
        .iter()
        .filter(|e| e.mac != NO_MAC)
        .filter_map(|e| Some((e.mac, e.name.as_deref()?)))
        .collect();
    let by_code = unique("mac names", &named)?;
    let mut out = String::new();
    heading(&mut out);
    out.push_str(
        "/// The UI Events `code` names of macOS virtual key codes, which hotkeys\n\
         /// are written with (see `Hotkeys` in app.proto).\n\
         enum KeyCodes {\n    \
         /// The name of the key with virtual key code `keyCode`, as\n    \
         /// `NSEvent.keyCode` gives it; nil for a key without one.\n    \
         static func domCode(mac keyCode: UInt16) -> String? {\n        \
         switch keyCode {\n",
    );
    for (code, name) in by_code {
        writeln!(out, "        case {code:#06x}: {name:?}").unwrap();
    }
    out.push_str("        default: nil\n        }\n    }\n}\n");
    Ok(out)
}

/// The Windows app's table: set-1 scan code to name.
pub fn generate_csharp(source: &str) -> Result<String, String> {
    let entries = parse(source)?;
    let mut named = Vec::new();
    for e in entries.iter().filter(|e| e.win != NO_CODE) {
        let Some(name) = e.name.as_deref() else {
            continue;
        };
        let (code, extended) = windows_scan_code(e)?;
        named.push(((extended, code), name));
    }
    let by_code = unique("Windows names", &named)?;
    let mut out = String::new();
    heading(&mut out);
    out.push_str(
        "#nullable enable\n\n\
         namespace InputWeave.Generated;\n\n\
         /// <summary>The UI Events <c>code</c> names of Windows scan codes, which hotkeys are\n\
         /// written with (see <c>Hotkeys</c> in app.proto).</summary>\n\
         public static class KeyCodes\n\
         {\n    \
         /// <summary>The name of the key with set-1 scan code <paramref name=\"scanCode\"/>, which\n    \
         /// comes with an 0xE0 prefix when <paramref name=\"extended\"/>; null for a key without\n    \
         /// one.</summary>\n    \
         public static string? DomCode(uint scanCode, bool extended) => (scanCode, extended) switch\n    \
         {\n",
    );
    for ((extended, code), name) in by_code {
        writeln!(out, "        ({code:#04x}u, {extended}) => {name:?},").unwrap();
    }
    out.push_str("        _ => null,\n    };\n}\n");
    Ok(out)
}

/// The names by code, in the order of the codes. Two names for one code
/// would make the table ambiguous.
fn unique<'a, T: Copy + Ord + std::fmt::Debug>(
    what: &str,
    pairs: &[(T, &'a str)],
) -> Result<BTreeMap<T, &'a str>, String> {
    let mut by_code = BTreeMap::new();
    for &(code, name) in pairs {
        if let Some(other) = by_code.insert(code, name) {
            return Err(format!("{what}: {code:?} is both {other} and {name}"));
        }
    }
    Ok(by_code)
}

/// The scan code of an entry, and whether it comes with an 0xE0 prefix.
fn windows_scan_code(e: &Entry) -> Result<(u8, bool), String> {
    let extended = match e.win >> 8 {
        0x00 => false,
        0xe0 => true,
        _ => {
            return Err(format!(
                "usage {:#06x}: unexpected Windows scan code {:#06x}",
                e.usage, e.win
            ));
        }
    };
    Ok(((e.win & 0xff) as u8, extended))
}

/// One `DOM_CODE(...)` entry on the Keyboard/Keypad page.
#[derive(Debug, PartialEq)]
struct Entry {
    usage: u16,
    evdev: u16,
    win: u16,
    mac: u16,
    name: Option<String>,
}

/// "No code" in each column of the source table.
const NO_MAC: u16 = 0xffff;
const NO_CODE: u16 = 0;

pub fn generate(source: &str) -> Result<String, String> {
    let entries = parse(source)?;
    let mut out = String::new();
    heading(&mut out);

    let mac: Vec<(u16, u16)> = entries
        .iter()
        .filter(|e| e.mac != NO_MAC)
        .map(|e| (e.usage, e.mac))
        .collect();
    let evdev: Vec<(u16, u16)> = entries
        .iter()
        .filter(|e| e.evdev != NO_CODE)
        .map(|e| (e.usage, e.evdev))
        .collect();
    let mut win = Vec::new();
    for e in entries.iter().filter(|e| e.win != NO_CODE) {
        let (code, extended) = windows_scan_code(e)?;
        win.push((e.usage, code, extended));
    }

    forward(&mut out, "to_mac", "u16", &mac, |c| format!("{c:#06x}"));
    reverse(&mut out, "from_mac", "code: u16", "code", &mac, |c| {
        format!("{c:#06x}")
    })?;
    let win_forward: Vec<(u16, (u8, bool))> = win.iter().map(|&(u, c, x)| (u, (c, x))).collect();
    forward(
        &mut out,
        "to_windows",
        "(u8, bool)",
        &win_forward,
        |(c, x)| format!("({c:#04x}, {x})"),
    );
    reverse(
        &mut out,
        "from_windows",
        "code: u8, extended: bool",
        "(code, extended)",
        &win_forward,
        |(c, x)| format!("({c:#04x}, {x})"),
    )?;
    forward(&mut out, "to_evdev", "u16", &evdev, |c| format!("{c:#06x}"));
    reverse(&mut out, "from_evdev", "code: u16", "code", &evdev, |c| {
        format!("{c:#06x}")
    })?;

    out.push_str("pub(crate) fn name(usage: u16) -> Option<&'static str> {\n");
    out.push_str("    Some(match usage {\n");
    for e in &entries {
        if let Some(name) = &e.name {
            writeln!(out, "        {:#06x} => {name:?},", e.usage).unwrap();
        }
    }
    out.push_str("        _ => return None,\n    })\n}\n");
    Ok(out)
}

fn forward<T: Copy>(
    out: &mut String,
    name: &str,
    ty: &str,
    pairs: &[(u16, T)],
    show: impl Fn(T) -> String,
) {
    writeln!(out, "pub(crate) fn {name}(usage: u16) -> Option<{ty}> {{").unwrap();
    out.push_str("    Some(match usage {\n");
    for &(usage, code) in pairs {
        writeln!(out, "        {usage:#06x} => {},", show(code)).unwrap();
    }
    out.push_str("        _ => return None,\n    })\n}\n\n");
}

/// A reverse lookup. Two usages sharing a native code would make it
/// ambiguous, so that is an error: the source table resolves the known
/// cases ([M1], [W1] in its notes) by leaving one side without a code.
fn reverse<T: Copy + Ord + std::fmt::Debug>(
    out: &mut String,
    name: &str,
    params: &str,
    scrutinee: &str,
    pairs: &[(u16, T)],
    show: impl Fn(T) -> String,
) -> Result<(), String> {
    let mut by_code: BTreeMap<T, u16> = BTreeMap::new();
    for &(usage, code) in pairs {
        if let Some(other) = by_code.insert(code, usage) {
            return Err(format!(
                "{name}: {code:?} maps to both usage {other:#06x} and {usage:#06x}"
            ));
        }
    }
    writeln!(out, "pub(crate) fn {name}({params}) -> Option<u16> {{").unwrap();
    writeln!(out, "    Some(match {scrutinee} {{").unwrap();
    for (code, usage) in by_code {
        writeln!(out, "        {} => {usage:#06x},", show(code)).unwrap();
    }
    out.push_str("        _ => return None,\n    })\n}\n\n");
    Ok(())
}

/// Reads every `DOM_CODE(usb, evdev, xkb, win, mac, code, id)` entry on
/// USB page 0x07, skipping commented-out ones and the reserved and error
/// usages below 0x04.
fn parse(source: &str) -> Result<Vec<Entry>, String> {
    let text: String = source
        .lines()
        .map(|line| match line.find("//") {
            Some(i) => &line[..i],
            None => line,
        })
        .collect::<Vec<_>>()
        .join(" ");
    let mut entries: Vec<Entry> = Vec::new();
    let mut rest = text.as_str();
    while let Some(start) = rest.find("DOM_CODE(") {
        rest = &rest[start + "DOM_CODE(".len()..];
        let end = rest
            .find(')')
            .ok_or("unterminated DOM_CODE entry".to_owned())?;
        let fields: Vec<&str> = rest[..end].split(',').map(str::trim).collect();
        rest = &rest[end..];
        let [usb, evdev, _xkb, win, mac, code, _id] = fields[..] else {
            return Err(format!("DOM_CODE entry with {} fields", fields.len()));
        };
        let usb = hex(usb)?;
        if usb >> 16 != 0x07 || usb & 0xffff < 0x04 {
            continue;
        }
        let name = match code {
            "NULL" => None,
            quoted => Some(
                quoted
                    .strip_prefix('"')
                    .and_then(|c| c.strip_suffix('"'))
                    .ok_or(format!("bad code name {quoted}"))?
                    .to_owned(),
            ),
        };
        let usage = (usb & 0xffff) as u16;
        if entries.iter().any(|e| e.usage == usage) {
            return Err(format!("usage {usage:#06x} listed twice"));
        }
        entries.push(Entry {
            usage,
            evdev: hex(evdev)? as u16,
            win: hex(win)? as u16,
            mac: hex(mac)? as u16,
            name,
        });
    }
    if entries.is_empty() {
        return Err("no keyboard entries found".to_owned());
    }
    entries.sort_by_key(|e| e.usage);
    Ok(entries)
}

fn hex(s: &str) -> Result<u32, String> {
    s.strip_prefix("0x")
        .and_then(|h| u32::from_str_radix(h, 16).ok())
        .ok_or_else(|| format!("expected a hex number, found {s:?}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"
  //            USB     evdev    XKB     Win     Mac   Code
  DOM_CODE(0x000000, 0x0000, 0x0000, 0x0000, 0xffff, NULL, NONE), // Invalid
  DOM_CODE(0x070001, 0x0000, 0x0000, 0x00ff, 0xffff, NULL, USB_ERROR_ROLL_OVER),
  DOM_CODE(0x070004, 0x001e, 0x0026, 0x001e, 0x0000, "KeyA", US_A), // aA
  DOM_CODE(0x070053, 0x0045, 0x004d, 0xe045, 0x0047, "NumLock",
             NUM_LOCK),
  //DOM_CODE(0x07009c, 0x0000, 0x0000, 0x0000, 0xffff, NULL, CLEAR), // Clear
  DOM_CODE(0x0c00b0, 0x00cf, 0x00d7, 0x0000, 0xffff, "MediaPlay", MEDIA_PLAY),
"#;

    #[test]
    fn keeps_keyboard_page_entries_only() {
        let entries = parse(SAMPLE).unwrap();
        let usages: Vec<u16> = entries.iter().map(|e| e.usage).collect();
        assert_eq!(usages, vec![0x04, 0x53]);
        assert_eq!(entries[1].win, 0xe045);
        assert_eq!(entries[1].name.as_deref(), Some("NumLock"));
    }

    #[test]
    fn rejects_ambiguous_reverse_mappings() {
        let clash = format!(
            "{SAMPLE}\n  DOM_CODE(0x070005, 0x0030, 0x0038, 0x0030, 0x0000, \"KeyB\", US_B),\n"
        );
        let err = generate(&clash).unwrap_err();
        assert!(err.contains("from_mac"), "{err}");
    }

    #[test]
    fn the_apps_tables_name_each_native_code() {
        let swift = generate_swift(SAMPLE).unwrap();
        assert!(swift.contains("        case 0x0000: \"KeyA\"\n"), "{swift}");
        assert!(
            swift.contains("        case 0x0047: \"NumLock\"\n"),
            "{swift}"
        );
        let csharp = generate_csharp(SAMPLE).unwrap();
        assert!(
            csharp.contains("        (0x1eu, false) => \"KeyA\",\n"),
            "{csharp}"
        );
        assert!(
            csharp.contains("        (0x45u, true) => \"NumLock\",\n"),
            "{csharp}"
        );
        assert!(csharp.contains("#nullable enable"), "{csharp}");
    }

    /// The committed file is exactly what the committed source generates.
    fn assert_up_to_date(output: &str) {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
        let source = std::fs::read_to_string(root.join(SOURCE)).unwrap();
        let committed = std::fs::read_to_string(root.join(output)).unwrap();
        let generated = outputs(&source)
            .unwrap()
            .into_iter()
            .find(|(path, _)| *path == output)
            .unwrap()
            .1;
        assert!(
            generated == committed,
            "{output} is stale; run `cargo xtask keymap`"
        );
    }

    #[test]
    fn committed_table_is_up_to_date() {
        assert_up_to_date(OUTPUT);
    }

    #[test]
    fn committed_swift_table_is_up_to_date() {
        assert_up_to_date(SWIFT_OUTPUT);
    }

    #[test]
    fn committed_csharp_table_is_up_to_date() {
        assert_up_to_date(CSHARP_OUTPUT);
    }
}
